  // Updates allowed directories based on MCP client roots, unless a newer
  // refresh started after this one's `generation` was taken (#5097).
  async function updateAllowedDirectoriesFromRoots(
    requestedRoots: Root[],
    generation: number,
  ) {
    const validRootDirs = await getValidRootDirectories(requestedRoots);
    if (generation !== rootsGeneration) {
      console.error(
        "Discarded a stale roots/list answer: a newer roots update has started",
      );
      return;
    }
    const validatedRootDirs = confineRoots(validRootDirs);
    if (validatedRootDirs.length > 0) {
      allowedDirectories = [...validatedRootDirs];
      rootsInForce = true;
      console.error(
        `Updated allowed directories from MCP roots: ${validatedRootDirs.length} valid directories`,
      );
    } else if (rootsInForce) {
      allowedDirectories = [];
      console.error(
        "No valid root directories provided by client; access revoked until it exposes a root again",
      );
    } else {
      console.error("No valid root directories provided by client");
    }
    logAllowedDirectories();
  }

  // Log the allowed directories now in force and where they came from (#4912).
  function logAllowedDirectories(): void {
    console.error(
      describeAllowedDirectories(
        allowedDirectories,
        rootsInForce
          ? {
              from: "roots",
              replacedCommandLine: initialAllowedDirectories.length > 0,
              confined: confining,
            }
          : { from: "command-line" },
      ),
    );
  }

  // True when the client's Roots are kept inside the command-line directories
  // (#3133). With none given there is nothing to confine them to.
  const confining =
    options.confineRoots === true && initialAllowedDirectories.length > 0;

  // The client's valid roots as the server will apply them: unchanged, or,
  // with --confine-roots, cut down to their overlap with the command-line
  // directories. A root outside all of them is dropped like an invalid one,
  // so roots that are all outside leave the state as invalid roots would.
  function confineRoots(validRootDirs: string[]): string[] {
    if (!confining) return validRootDirs;
    const { confined, ignored } = confineRootsToDirectories(
      validRootDirs,
      initialAllowedDirectories,
    );
    if (ignored.length > 0) {
      console.error(
        `Ignored client roots outside the command-line directories (--confine-roots): ${ignored.join(", ")}`,
      );
    }
    return confined;
  }

  // Handles dynamic roots updates during runtime, when client sends "roots/list_changed" notification, server fetches the updated roots and replaces all allowed directories with the new roots.
  server.server.setNotificationHandler(
    "notifications/roots/list_changed",
    async () => {
      const generation = ++rootsGeneration;
      const settle = installBarrier();
      try {
        // Request the updated roots list from the client
        const response = await server.server.listRoots();
        /* v8 ignore else -- the SDK validates the roots/list result against ListRootsResultSchema, which requires roots, so the implicit else cannot run */
        if (response && "roots" in response) {
          await updateAllowedDirectoriesFromRoots(response.roots, generation);
        }
      } catch (error) {
        console.error(
          "Failed to request roots from client:",
          error instanceof Error ? error.message : String(error),
        );
      } finally {
        settle();
      }
    },
  );

  // Handles post-initialization setup, specifically checking for and fetching
  // MCP roots. Only a 2025-era connection initializes, so this never runs on
  // 2026-07-28, where Roots is unavailable (and deprecated). The initial load claims its generation and installs its barrier
  // here, synchronously, before any roots/list_changed handled afterwards can
  // claim a newer one.
  server.server.oninitialized = () => {
    const generation = ++rootsGeneration;
    const settle = installBarrier();
    // Not awaited: oninitialized is synchronous. Tool calls wait on the
    // barrier, which settles when initialize() finishes; it never rejects.
    void initialize(generation).finally(settle);
  };

  async function initialize(generation: number): Promise<void> {
    const clientCapabilities = server.server.getClientCapabilities();

    if (clientCapabilities?.roots) {
      try {
        const response = await server.server.listRoots();
        /* v8 ignore else -- the SDK validates the roots/list result against ListRootsResultSchema, which requires roots, so the else cannot run */
        if (response && "roots" in response) {
          await updateAllowedDirectoriesFromRoots(response.roots, generation);
        } else {
          console.error(
            "Client returned no roots set, keeping current settings",
          );
        }
      } catch (error) {
        console.error(
          "Failed to request initial roots from client:",
          error instanceof Error ? error.message : String(error),
        );
        logAllowedDirectories();
      }
    } else {
      if (allowedDirectories.length > 0) {
        console.error(
          "Client does not support MCP Roots, using allowed directories set from server args:",
          allowedDirectories,
        );
        logAllowedDirectories();
      } else {
        // Nothing could ever be allowed in this session, so fail visibly
        // rather than serve every call with "Access denied" (#4992): log the
        // reason and close the connection. Throwing here would only reach the
        // SDK's onerror, which the client never sees.
        const error = new Error(NO_ALLOWED_DIRECTORIES_ERROR);
        console.error(`Error: ${error.message}`);
        await server.close();
        options.onCannotOperate?.(error);
      }
    }
  }

  return server;
}
